      "id": "NEG-28",
      "sourceCardNo": 28,
      "name": "The Ackerman Concession Model",
      "stage": "Anchoring, Framing & Concession Dynamics",
      "kicker": "Anchoring",
      "scenario": "Commercial buyer purchasing specialized manufacturing tooling with a list price of $500,000, targeting an acquisition price of $400,000.",
      "scenarioSize": 8.5,
      "nameSize": 12,
      "schematic": "Step at step 4 of 4",
      "script": [
        "Round 1 (65%): \"Our opening capital allocation is $260,000.\"",
        "Round 2 (85%): \"We reviewed our operational funds; we can push to $340,000.\"",
        "Round 3 (95%): \"We secured an executive sign-off to reach $380,000.\"",
        "Round 4 (100%): \"We have exhausted our reserve. The absolute maximum we can execute is $401,350, and we will sign the agreement today.\""
      ],
      "defense": "Name the curve: this is the Ackerman sequence; the final figure is still below our cost of delivery; restructure scope.",
      "defenseSize": 6.5,
      "origin": {
        "line": "Ackerman"
      },
      "figure": {
        "svgShape": "negotiation-figure",
        "parametricParams": {
          "family": "step",
          "divisions": 4,
          "mark": 4
        }
      },
      "originFull": "Algorithmic Concession Scheduling combines anchoring, diminishing concession rates, and psychological precision into a structured bidding sequence (65% → 85% → 95% → 100% of target).",
      "defenseFull": "Neutralize the formulaic sequence: \"This sequence follows a classic Ackerman concession curve. While we recognize the structural discipline, your final figure remains below our cost of delivery. We need to restructure the project scope.\"",
      "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\" aria-label=\"Parametric diagram of the card principle\"><line x1=\"72\" y1=\"296\" x2=\"136\" y2=\"296\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/><line x1=\"136\" y1=\"296\" x2=\"136\" y2=\"254\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" opacity=\"0.35\" vector-effect=\"non-scaling-stroke\"/><circle cx=\"104\" cy=\"296\" r=\"3.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.1\" opacity=\"0.35\" vector-effect=\"non-scaling-stroke\"/><line x1=\"136\" y1=\"254\" x2=\"200\" y2=\"254\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/><line x1=\"200\" y1=\"254\" x2=\"200\" y2=\"212\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" opacity=\"0.35\" vector-effect=\"non-scaling-stroke\"/><circle cx=\"168\" cy=\"254\" r=\"3.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.1\" opacity=\"0.35\" vector-effect=\"non-scaling-stroke\"/><line x1=\"200\" y1=\"212\" x2=\"264\" y2=\"212\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/><line x1=\"264\" y1=\"212\" x2=\"264\" y2=\"170\" stroke=\"currentColor\" stroke-width=\"1.4\" stroke-linecap=\"round\" opacity=\"0.35\" vector-effect=\"non-scaling-stroke\"/><circle cx=\"232\" cy=\"212\" r=\"3.6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.1\" opacity=\"0.35\" vector-effect=\"non-scaling-stroke\"/><line x1=\"264\" y1=\"170\" x2=\"328\" y2=\"170\" stroke=\"currentColor\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\"0.95\" vector-effect=\"non-scaling-stroke\"/><line x1=\"328\" y1=\"170\" x2=\"328\" y2=\"128\" stroke=\"currentColor\" stroke-width=\"3.2\" stroke-linecap=\"round\" opacity=\"0.9\" vector-effect=\"non-scaling-stroke\"/><circle cx=\"296\" cy=\"170\" r=\"7\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"2.4\" opacity=\"0.95\" vector-effect=\"non-scaling-stroke\"/><line x1=\"72\" y1=\"296\" x2=\"328\" y2=\"296\" stroke=\"currentColor\" stroke-width=\"1.1\" stroke-linecap=\"round\" opacity=\"0.2\" vector-effect=\"non-scaling-stroke\"/></svg>"
